#!/usr/bin/env python3
"""Line-numbered contents blocks for large reference files.

Every skills/*/references/*.md over THRESHOLD bytes starts (right after its H1)
with a generated block listing each `## ` section and its line range, so a
reader can open the block, then Read only the section it needs with
offset/limit instead of loading 60 KB:

    <!-- contents: generated by bin/contents.py; read a section with Read offset=START limit=END-START+1 -->
    ## Contents

    - L14-31 **Common Pitfalls**: what goes wrong most
    - L33-120 **Services**: ...
    <!-- /contents -->

A hand-written "## Contents" list is folded in: its per-section descriptions are
kept (matched by section title) and the old list is removed, so there is one
contents block per file.

Usage:
    python3 bin/contents.py           # rewrite the blocks
    python3 bin/contents.py --check   # exit 1 if any block is missing or stale (CI)

Python 3.9+, standard library only.
"""
from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent
THRESHOLD = 30 * 1024
START = "<!-- contents: generated by bin/contents.py; read a section with Read offset=START limit=END-START+1 -->"
END = "<!-- /contents -->"
SEP = re.compile(r"\s+(?:—|--|-|:)\s+")


def targets() -> list[Path]:
    return [p for p in sorted(REPO.glob("skills/*/references/*.md"))
            if p.stat().st_size > THRESHOLD and p.name != "version-table.md"]


TOC_TITLES = {"## Contents", "## Table of Contents"}
ENTRY = re.compile(r"- L\d+-\d+ \*\*(.+?)\*\*(?:: (.*))?$")


def strip_block(lines: list[str]) -> tuple[list[str], dict[str, str]]:
    """Remove a generated block and a hand-written contents section; return their descriptions."""
    out, descs, i = [], {}, 0
    while i < len(lines):
        line = lines[i]
        if line == START:
            j = lines.index(END, i)
            for entry in lines[i:j]:
                m = ENTRY.match(entry)
                if m and m.group(2):
                    descs.setdefault(m.group(1), m.group(2))
            i = j + 1
            while i < len(lines) and not lines[i].strip():
                i += 1
            continue
        if line.strip() in TOC_TITLES:
            j = i + 1
            while j < len(lines) and not lines[j].startswith("## "):
                m = re.match(r"\s*[-*\d.]+\s+(?:\[([^\]]+)\]\([^)]*\)|(.+?))(?:" + SEP.pattern + r"(.+))?$", lines[j])
                if m:
                    title = (m.group(1) or m.group(2) or "").strip()
                    if m.group(3):
                        descs.setdefault(title, m.group(3).strip())
                j += 1
            i = j
            continue
        out.append(line)
        i += 1
    return out, descs


def section_heads(lines: list[str]) -> list[int]:
    heads, in_code = [], False
    for n, l in enumerate(lines):
        if l.lstrip().startswith("```"):
            in_code = not in_code
        elif not in_code and l.startswith("## ") and l.strip() not in TOC_TITLES:
            heads.append(n)
    return heads


def build(path: Path) -> str:
    text = path.read_text(encoding="utf-8")
    trailing = text.endswith("\n")
    raw = text[:-1].split("\n") if trailing else text.split("\n")
    lines, descs = strip_block(raw)
    h1 = next((n for n, l in enumerate(lines) if l.startswith("# ")), 0)
    rest = lines[h1 + 1:]
    while rest and not rest[0].strip():
        rest = rest[1:]
    titles = [lines[n][3:].strip() for n in section_heads(lines)]
    placeholder = [START, "## Contents", ""] + ["- L0-0" for _ in titles] + [END, ""]
    final = lines[: h1 + 1] + [""] + placeholder + rest
    heads = [n for n in section_heads(final) if final[n] != "## Contents"]
    first = final.index(START) + 3
    for k, n in enumerate(heads):
        end = heads[k + 1] if k + 1 < len(heads) else len(final)
        title = final[n][3:].strip()
        desc = descs.get(title, "")
        if not desc:
            desc = next((d for t, d in descs.items() if len(t) > 3 and (title.startswith(t) or t.startswith(title))), "")
        final[first + k] = f"- L{n + 1}-{end} **{title}**" + (f": {desc}" if desc else "")
    return "\n".join(final) + ("\n" if trailing else "")


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--check", action="store_true")
    args = ap.parse_args()
    stale = []
    for p in targets():
        new = build(p)
        if new != p.read_text(encoding="utf-8"):
            stale.append(p)
            if not args.check:
                p.write_text(new, encoding="utf-8")
    rel = [str(p.relative_to(REPO)) for p in stale]
    # The owning SKILL.md must route readers through the block (R12).
    unrouted = []
    for p in targets():
        skill_md = p.parent.parent / "SKILL.md"
        lines = [l for l in skill_md.read_text(encoding="utf-8").splitlines() if "Contents block" in l]
        if not any(f"`{p.name}`" in l for l in lines):
            unrouted.append(f"{skill_md.relative_to(REPO)} has no Contents-block routing line naming `{p.name}`")
    if args.check:
        for u in unrouted:
            print(u)
        rel += unrouted
        for r in rel:
            print(f"stale or missing contents block: {r} (run python3 bin/contents.py)")
        print(f"{len(rel)} stale contents block(s) in {len(targets())} large reference(s)")
        return 1 if rel else 0
    print(f"rewrote {len(rel)} of {len(targets())} large reference(s)" + (": " + ", ".join(rel) if rel else ""))
    return 0


if __name__ == "__main__":
    sys.exit(main())
